import logging
import re
import base64
from pathlib import Path
from io import BytesIO
from typing import List, Tuple, Dict, Any, Union, Optional

import pandas as pd
import openpyxl
from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
from openpyxl.utils import get_column_letter
from openpyxl.cell.rich_text import CellRichText, TextBlock
from openpyxl.cell.text import InlineFont
from openpyxl.worksheet.worksheet import Worksheet
from openpyxl.drawing.image import Image as XLImage
from PIL import Image as PILImage

# Markdown Parser Library
from markdown_it import MarkdownIt
from mineru.cli.markdown_parser import MarkdownParser

# --- Configuration & Constants ---
class AppConfig:
    """Configuration constants for the Markdown to Excel process."""
    # Excel Sheet Names
    EXCEL_TOC_SHEET_NAME = "Table of Contents"
    EXCEL_MAIN_SHEET_NAME = "Markdown_Output"

    # Image & Layout settings
    DEFAULT_EXCEL_COLS = 10
    IMAGE_MAX_WIDTH_IN_TABLE_PX = 120
    IMAGE_MAX_WIDTH_IN_CELL_PX = 600
    IMAGE_MAX_ROW_HEIGHT_PT = 409
    
    # Conversion ratios
    PIXELS_TO_CHAR_RATIO = 7.0
    PIXELS_TO_POINTS_RATIO = 0.75
    ROW_HEIGHT_BUFFER_PT = 5

    # Column Widths
    DEFAULT_MAX_COL_WIDTH = 80
    MIN_COL_WIDTH = 10

# --- Logger Setup (Simplified) ---
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)



# --- Excel Writer Class ---
class MarkdownToExcelWriter:
    """
    Writes structured blocks to an Excel file with styling.
    """
    class ExcelStyles:
        DEFAULT_FONT = Font(name='Calibri', size=11)
        H1_FONT = Font(bold=True, size=20, name='Calibri')
        H2_FONT = Font(bold=True, size=16, name='Calibri')
        H3_FONT = Font(bold=True, size=14, name='Calibri')
        H4_FONT = Font(bold=True, size=12, name='Calibri')
        H5_FONT = Font(bold=True, size=11, name='Calibri')
        H6_FONT = Font(bold=True, size=11, name='Calibri')
        QUOTE_FONT = Font(italic=True, name='Calibri')
        CODE_FONT = Font(name='Consolas', size=10)
        LINK_FONT = Font(color="0563C1", underline="single", name='Calibri')
        TEXT_ALIGNMENT = Alignment(wrap_text=True, vertical='top', horizontal='left')
        LIST_ALIGNMENT = Alignment(wrap_text=True, vertical='top', horizontal='left', indent=1)
        QUOTE_ALIGNMENT = Alignment(wrap_text=True, vertical='top', horizontal='left', indent=1)
        CODE_ALIGNMENT = Alignment(wrap_text=True, vertical='top', horizontal='left')
        TABLE_HEADER_ALIGNMENT = Alignment(wrap_text=True, vertical='center', horizontal='center')
        THIN_BORDER = Border(left=Side(style='thin'), right=Side(style='thin'), top=Side(style='thin'), bottom=Side(style='thin'))
        MEDIUM_BOTTOM_BORDER = Border(bottom=Side(style='medium'))
        MEDIUM_LEFT_BORDER = Border(left=Side(style='medium'))
        TABLE_HEADER_FONT = Font(bold=True, color="FFFFFF", name='Calibri', size=11)
        TABLE_HEADER_FILL = PatternFill(start_color="4F81BD", end_color="4F81BD", fill_type="solid")
        EVEN_ROW_FILL = PatternFill(start_color="FFFFFF", end_color="FFFFFF", fill_type="solid")
        ODD_ROW_FILL = PatternFill(start_color="F2F2F2", end_color="F2F2F2", fill_type="solid")
        CODE_FILL = PatternFill(start_color="F5F5F5", end_color="F5F5F5", fill_type="solid")

    def __init__(self, output_path: str | Path, base_dir: str | Path = None, options: Optional[Dict[str, Any]] = None):
        self.output_path = Path(output_path)
        self.output_path.parent.mkdir(parents=True, exist_ok=True)
        self.base_dir = Path(base_dir) if base_dir else self.output_path.parent
        self.md_inline_parser = MarkdownIt('gfm-like').enable(['strikethrough', 'table'])
        self.column_max_widths: Dict[int, int] = {}

        if options is None:
            options = {}
        self.limit_max_width = options.get('limit_max_width', False)
        try:
            self.max_width = int(options.get('max_width', AppConfig.DEFAULT_MAX_COL_WIDTH))
        except (ValueError, TypeError):
            self.max_width = AppConfig.DEFAULT_MAX_COL_WIDTH
        
        self._block_writers = {
            'table': self._write_table_block,
            'list_item': self._write_list_item_block,
            'code': self._write_code_block,
            'image': self._write_image_block,
            'heading': self._write_heading_block,
            'text': self._write_text_block,
            'hr': self._write_hr_block,
            'blockquote': self._write_blockquote_block,
        }

    def write_blocks_to_excel(self, blocks: list) -> str:
        try:
            self._write_blocks_to_excel_internal(blocks, self.output_path)
            return str(self.output_path)
        except Exception:
            logger.exception(f"Error writing to Excel file '{self.output_path.name}'.")
            raise

    def _update_column_width(self, col_idx: int, content: Any):
        if not content: return
        cell_text = ""
        if isinstance(content, str): cell_text = content
        elif isinstance(content, (int, float)): cell_text = str(content)
        elif isinstance(content, CellRichText):
            cell_text = "".join(str(part.text) if isinstance(part, TextBlock) else str(part) for part in content)
        
        length = 0
        for char in cell_text:
            length += 2 if '\u4e00' <= char <= '\u9fff' else 1

        if length > self.column_max_widths.get(col_idx, 0):
            self.column_max_widths[col_idx] = length

    def _parse_rich_text(self, text: str) -> Union[str, CellRichText]:
        if not isinstance(text, str) or not text.strip(): return text
        cleaned_text = re.sub(r'[\x00-\x08\x0b\x0c\x0e-\x1f\x7f-\x84\x86-\x9f]', '', text)
        if not cleaned_text.strip(): return cleaned_text

        default_calibri_font = InlineFont(rFont='Calibri')
        tokens = self.md_inline_parser.parseInline(cleaned_text.strip())
        parts = []
        font_stack = []

        for token in tokens[0].children:
            content = token.content
            if token.type == 'text' and content and content.strip():
                active_font = font_stack[-1] if font_stack else default_calibri_font
                parts.append(TextBlock(active_font, content))
            elif token.type in ['strong_open', 'em_open', 's_open']:
                is_bold = (font_stack[-1].b if font_stack and font_stack[-1].b else False) or (token.type == 'strong_open')
                is_italic = (font_stack[-1].i if font_stack and font_stack[-1].i else False) or (token.type == 'em_open')
                is_strike = (font_stack[-1].strike if font_stack and font_stack[-1].strike else False) or (token.type == 's_open')
                font_stack.append(InlineFont(rFont='Calibri', b=is_bold, i=is_italic, strike=is_strike))
            elif token.type in ['strong_close', 'em_close', 's_close']:
                if font_stack: font_stack.pop()
            elif token.type == 'code_inline' and content:
                code_font = InlineFont(rFont='Consolas', size=10)
                parts.append(TextBlock(code_font, content))
                
        if not parts: return cleaned_text
        merged_parts = [parts[0]]
        for part in parts[1:]:
            last_part = merged_parts[-1]
            if last_part.font.__dict__ == part.font.__dict__:
                last_part.text += part.text
            else:
                merged_parts.append(part)
        
        if len(merged_parts) == 1 and merged_parts[0].font.__dict__ == default_calibri_font.__dict__:
            return merged_parts[0].text
        return CellRichText(merged_parts)

    def _write_table_block(self, worksheet: Worksheet, block: tuple, current_row: int, max_cols: int, toc_entries: list, sheet_name: str) -> int:
        _, df, alignments = block
        image_b64_re = re.compile(r'!\[.*?\]\(data:image\/[a-zA-Z]+;base64,([a-zA-Z0-9+/=]+)\)')
        start_table_row = current_row
        
        # Header
        for c_idx, value in enumerate(df.columns, 1):
            cell = worksheet.cell(row=start_table_row, column=c_idx, value=str(value).strip())
            cell.font = self.ExcelStyles.TABLE_HEADER_FONT
            cell.fill = self.ExcelStyles.TABLE_HEADER_FILL
            cell.alignment = self.ExcelStyles.TABLE_HEADER_ALIGNMENT
            cell.border = self.ExcelStyles.THIN_BORDER
            self._update_column_width(c_idx, str(value).strip()) 

        # Rows
        for r_idx, row_data in enumerate(df.itertuples(index=False), 1):
            excel_row_num = start_table_row + r_idx
            row_fill = self.ExcelStyles.EVEN_ROW_FILL if (r_idx-1) % 2 == 0 else self.ExcelStyles.ODD_ROW_FILL
            max_image_height_in_row = 0

            for c_idx, value in enumerate(row_data, 1):
                cell = worksheet.cell(row=excel_row_num, column=c_idx)
                col_alignment = alignments[c_idx - 1] if c_idx <= len(alignments) else 'left'
                cell.alignment = Alignment(wrap_text=True, vertical='top', horizontal=col_alignment)
                cell.border = self.ExcelStyles.THIN_BORDER
                cell.fill = row_fill
                cell.font = self.ExcelStyles.DEFAULT_FONT
                
                value_str = str(value) if not pd.isna(value) else ""
                match_b64 = image_b64_re.search(value_str.strip())
                image_path_re = re.compile(r'!\[(.*?)\]\((.*?)\)')
                match_path = image_path_re.search(value_str.strip())

                if match_b64:
                    try:
                        base64_data = match_b64.group(1)
                        image_bytes = base64.b64decode(base64_data)
                        pil_img = PILImage.open(BytesIO(image_bytes))
                        img = XLImage(BytesIO(image_bytes))
                        
                        max_width_px = AppConfig.IMAGE_MAX_WIDTH_IN_TABLE_PX
                        if pil_img.width > max_width_px:
                            ratio = max_width_px / float(pil_img.width)
                            img.width = max_width_px
                            img.height = int(pil_img.height * ratio)
                        
                        max_image_height_in_row = max(max_image_height_in_row, img.height)
                        col_letter = get_column_letter(c_idx)
                        required_width = img.width / AppConfig.PIXELS_TO_CHAR_RATIO + 1
                        current_col_width = worksheet.column_dimensions[col_letter].width or 0
                        worksheet.column_dimensions[col_letter].width = max(current_col_width, required_width)

                        cell.alignment = Alignment(vertical='center', horizontal='center')
                        worksheet.add_image(img, cell.coordinate)
                        cell.value = '' 
                    except Exception:
                        cell.value = value_str 
                        self._update_column_width(c_idx, value_str)
                elif match_path:
                    try:
                        rel_path = match_path.group(2)
                        full_path = self.base_dir / rel_path
                        
                        if full_path.exists():
                            pil_img = PILImage.open(full_path)
                            img = XLImage(str(full_path))
                            
                            max_width_px = AppConfig.IMAGE_MAX_WIDTH_IN_TABLE_PX
                            if pil_img.width > max_width_px:
                                ratio = max_width_px / float(pil_img.width)
                                img.width = max_width_px
                                img.height = int(pil_img.height * ratio)
                            
                            max_image_height_in_row = max(max_image_height_in_row, img.height)
                            col_letter = get_column_letter(c_idx)
                            required_width = img.width / AppConfig.PIXELS_TO_CHAR_RATIO + 1
                            current_col_width = worksheet.column_dimensions[col_letter].width or 0
                            worksheet.column_dimensions[col_letter].width = max(current_col_width, required_width)

                            cell.alignment = Alignment(vertical='center', horizontal='center')
                            worksheet.add_image(img, cell.coordinate)
                            cell.value = ''
                        else:
                            cell.value = value_str
                            self._update_column_width(c_idx, value_str)
                    except Exception:
                        cell.value = value_str
                        self._update_column_width(c_idx, value_str)
                else:
                    numeric_value = None
                    try:
                        if value_str.strip(): numeric_value = pd.to_numeric(value_str, errors='raise')
                    except (ValueError, TypeError): pass

                    if numeric_value is not None:
                        cell.value = numeric_value
                    else:
                        try:
                            cell.value = self._parse_rich_text(value_str)
                        except Exception:
                            cell.value = value_str.strip()
                    self._update_column_width(c_idx, cell.value)
            
            if max_image_height_in_row > 0:
                row_height = max_image_height_in_row * AppConfig.PIXELS_TO_POINTS_RATIO + AppConfig.ROW_HEIGHT_BUFFER_PT
                worksheet.row_dimensions[excel_row_num].height = row_height

        return current_row + df.shape[0] + 2
    
    def _write_blockquote_block(self, worksheet: Worksheet, block: tuple, current_row: int, max_cols: int, toc_entries: list, sheet_name: str) -> int:
        _, nested_blocks = block
        start_row = current_row
        for nested_block in nested_blocks:
            current_row = self._write_block_dispatcher(worksheet, nested_block, current_row, max_cols, toc_entries, sheet_name, is_nested=True)
        
        if start_row < current_row:
             for r in range(start_row, current_row):
                cell = worksheet.cell(row=r, column=1)
                new_border = Border(
                    left=self.ExcelStyles.MEDIUM_LEFT_BORDER.left,
                    right=cell.border.right,
                    top=cell.border.top,
                    bottom=cell.border.bottom
                )
                cell.border = new_border
                cell.alignment = self.ExcelStyles.QUOTE_ALIGNMENT
                cell.font = self.ExcelStyles.QUOTE_FONT
        return current_row

    def _write_code_block(self, worksheet: Worksheet, block: tuple, current_row: int, max_cols: int, toc_entries: list, sheet_name: str) -> int:
        _, code_content = block
        num_lines = code_content.count('\n') + 1
        worksheet.merge_cells(start_row=current_row, start_column=1, end_row=current_row + num_lines - 1, end_column=max_cols)
        cell = worksheet.cell(row=current_row, column=1, value=code_content)
        cell.font = self.ExcelStyles.CODE_FONT
        cell.alignment = self.ExcelStyles.CODE_ALIGNMENT
        self._update_column_width(1, code_content) 
        
        thin_side = Side(style='thin')
        for r in range(current_row, current_row + num_lines):
            for c in range(1, max_cols + 1):
                current_cell = worksheet.cell(row=r, column=c)
                current_cell.fill = self.ExcelStyles.CODE_FILL
                border = Border(
                    left=thin_side if c == 1 else current_cell.border.left,
                    right=thin_side if c == max_cols else current_cell.border.right,
                    top=thin_side if r == current_row else current_cell.border.top,
                    bottom=thin_side if r == current_row + num_lines - 1 else current_cell.border.bottom
                )
                current_cell.border = border
        return current_row + num_lines + 1

    def _write_image_block(self, worksheet: Worksheet, block: tuple, current_row: int, max_cols: int, toc_entries: list, sheet_name: str) -> int:
        _, alt_text, image_data = block
        try:
            pil_img = None
            img = None
            
            if ';base64,' in image_data:
                _, data = image_data.split(';base64,')
                image_bytes = base64.b64decode(data)
                pil_img = PILImage.open(BytesIO(image_bytes))
                img = XLImage(BytesIO(image_bytes))
            else:
                image_path = self.base_dir / image_data
                if image_path.exists():
                    pil_img = PILImage.open(image_path)
                    img = XLImage(str(image_path))

            if img:
                max_width_px = AppConfig.IMAGE_MAX_WIDTH_IN_CELL_PX
                if pil_img.width > max_width_px:
                    ratio = max_width_px / float(pil_img.width)
                    img.width = max_width_px
                    img.height = int(pil_img.height * ratio)

                img_height_pt = img.height * AppConfig.PIXELS_TO_POINTS_RATIO
                if img_height_pt > AppConfig.IMAGE_MAX_ROW_HEIGHT_PT:
                    height_ratio = AppConfig.IMAGE_MAX_ROW_HEIGHT_PT / img_height_pt
                    img.height = int(img.height * height_ratio)
                    img.width = int(img.width * height_ratio)
                    img_height_pt = AppConfig.IMAGE_MAX_ROW_HEIGHT_PT

                worksheet.merge_cells(start_row=current_row, start_column=1, end_row=current_row, end_column=max_cols)
                worksheet.row_dimensions[current_row].height = img_height_pt
                worksheet.add_image(img, f'A{current_row}')
                return current_row + 2
            else:
                cell = worksheet.cell(row=current_row, column=1, value=f"Image: {alt_text} ({image_data})")
                self._update_column_width(1, cell.value)
                return current_row + 2
        except Exception:
            cell = worksheet.cell(row=current_row, column=1, value=f"Failed to load image: {alt_text}")
            self._update_column_width(1, cell.value)
            return current_row + 2
    
    def _write_list_item_block(self, worksheet: Worksheet, block: tuple, current_row: int, max_cols: int, toc_entries: list, sheet_name: str) -> int:
        _, level, list_type, item_counter, nested_blocks = block
        level_bullets = ['•', '◦', '▪']
        prefix = level_bullets[level % len(level_bullets)] if list_type == 'bullet' else f"{item_counter}."
        first_line_written = False
        
        for nested_block in nested_blocks:
            if not first_line_written and nested_block[0] == 'text':
                worksheet.merge_cells(start_row=current_row, start_column=1, end_row=current_row, end_column=max_cols)
                cell = worksheet.cell(row=current_row, column=1)
                cell.font = self.ExcelStyles.DEFAULT_FONT
                cell.alignment = Alignment(wrap_text=True, vertical='top', horizontal='left', indent=level + 1)
                content = nested_block[1]
                try:
                    parsed = self._parse_rich_text(content)
                    if isinstance(parsed, CellRichText):
                        cell.value = CellRichText([TextBlock(self.ExcelStyles.DEFAULT_FONT, f"{prefix} ")] + parsed.text)
                    else:
                        cell.value = f"{prefix} {parsed}"
                except Exception:
                    cell.value = f"{prefix} {content}"
                self._update_column_width(1, cell.value)
                current_row += 1
                first_line_written = True
            else:
                current_row = self._write_block_dispatcher(worksheet, nested_block, current_row, max_cols, toc_entries, sheet_name, is_nested=True)
        
        if not first_line_written:
            cell = worksheet.cell(row=current_row, column=1, value=prefix)
            cell.alignment = Alignment(wrap_text=True, vertical='top', horizontal='left', indent=level + 1)
            self._update_column_width(1, cell.value)
            current_row +=1
        return current_row
    
    def _write_heading_block(self, worksheet: Worksheet, block: tuple, current_row: int, max_cols: int, toc_entries: list, sheet_name: str) -> int:
        _, level, title_text = block
        worksheet.merge_cells(start_row=current_row, start_column=1, end_row=current_row, end_column=max_cols)
        cell = worksheet.cell(row=current_row, column=1)
        if level <= 2:
            toc_entries.append((level, title_text, f"'{sheet_name}'!A{current_row}"))

        fonts = [self.ExcelStyles.H1_FONT, self.ExcelStyles.H2_FONT, self.ExcelStyles.H3_FONT, self.ExcelStyles.H4_FONT, self.ExcelStyles.H5_FONT, self.ExcelStyles.H6_FONT]
        cell.font = fonts[level-1]
        worksheet.row_dimensions[current_row].height = fonts[level-1].size * 1.5
        try:
            cell.value = self._parse_rich_text(title_text)
        except Exception:
            cell.value = title_text
        self._update_column_width(1, cell.value)
        return current_row + 2

    def _write_text_block(self, worksheet: Worksheet, block: tuple, current_row: int, max_cols: int, toc_entries: list, sheet_name: str) -> int:
        LINK_RE = re.compile(r'^\s*\[(.*?)\]\((.*?)\)\s*$')
        _, text_content = block
        lines = text_content.split('\n')
        for line in lines:
            stripped = line.strip()
            if not stripped:
                current_row += 1
                continue
            
            worksheet.merge_cells(start_row=current_row, start_column=1, end_row=current_row, end_column=max_cols)
            cell = worksheet.cell(row=current_row, column=1)
            cell.alignment = self.ExcelStyles.TEXT_ALIGNMENT
            cell.font = self.ExcelStyles.DEFAULT_FONT
            
            link_match = LINK_RE.match(stripped)
            if link_match:
                link_text, url = link_match.groups()
                cell.value = link_text
                cell.hyperlink = url
                cell.font = self.ExcelStyles.LINK_FONT
            else:
                try:
                    cell.value = self._parse_rich_text(line)
                except Exception:
                    cell.value = line
            self._update_column_width(1, cell.value)
            current_row += 1
        return current_row + 1

    def _write_hr_block(self, worksheet: Worksheet, block: tuple, current_row: int, max_cols: int, toc_entries: list, sheet_name: str) -> int:
        worksheet.merge_cells(start_row=current_row, start_column=1, end_row=current_row, end_column=max_cols)
        cell = worksheet.cell(row=current_row, column=1)
        cell.border = self.ExcelStyles.MEDIUM_BOTTOM_BORDER
        return current_row + 1

    def _write_block_dispatcher(self, worksheet: Worksheet, block: tuple, current_row: int, max_cols: int, toc_entries: list, sheet_name: str, is_nested: bool = False) -> int:
        writer_func = self._block_writers.get(block[0])
        if writer_func:
            return writer_func(worksheet, block, current_row, max_cols, toc_entries, sheet_name)
        return current_row

    def _write_toc(self, worksheet: Worksheet, toc_entries: list) -> None:
        worksheet.cell(row=1, column=1, value="Table of Contents").font = Font(bold=True, size=24, name='Calibri')
        worksheet.merge_cells('A1:D1')
        link_font = Font(color="0563C1", underline="single", name='Calibri')
        current_row = 3
        
        if not toc_entries:
            worksheet.cell(row=current_row, column=1, value="No H1 or H2 headers found.")
            return

        for level, text, target_link in toc_entries:
            cell = worksheet.cell(row=current_row, column=1)
            cell.value = text
            cell.hyperlink = f"#{target_link}"
            cell.font = link_font
            cell.alignment = Alignment(indent=(level - 1))
            current_row += 1
        worksheet.column_dimensions['A'].width = AppConfig.DEFAULT_MAX_COL_WIDTH
    
    def _apply_column_widths(self, worksheet: Worksheet) -> None:
        for col_idx, max_length in self.column_max_widths.items():
            col_letter = get_column_letter(col_idx)
            final_width = max_length + 5
            current_width = worksheet.column_dimensions[col_letter].width or 0
            final_width = max(final_width, current_width)
            
            if self.limit_max_width:
                final_width = min(final_width, self.max_width)
            else:
                final_width = min(final_width, AppConfig.DEFAULT_MAX_COL_WIDTH)
            
            final_width = max(final_width, AppConfig.MIN_COL_WIDTH)
            worksheet.column_dimensions[col_letter].width = final_width
    
    def _write_blocks_to_excel_internal(self, blocks: list, excel_path: Path) -> None:
        self.column_max_widths = {}
        max_cols = AppConfig.DEFAULT_EXCEL_COLS
        df_blocks = [b[1] for b in blocks if b[0] == 'table' and not b[1].empty]
        if df_blocks:
            max_cols = max(df.shape[1] for df in df_blocks if not df.empty)
            max_cols = max(max_cols, AppConfig.DEFAULT_EXCEL_COLS)

        with pd.ExcelWriter(str(excel_path), engine='openpyxl') as writer:
            workbook = writer.book
            toc_sheet = workbook.create_sheet(AppConfig.EXCEL_TOC_SHEET_NAME, 0)
            toc_sheet.sheet_view.showGridLines = False
            main_sheet = workbook.create_sheet(AppConfig.EXCEL_MAIN_SHEET_NAME, 1)
            main_sheet.sheet_view.showGridLines = False
            
            if "Sheet1" in workbook.sheetnames: del workbook["Sheet1"]
            writer.sheets[AppConfig.EXCEL_MAIN_SHEET_NAME] = main_sheet

            toc_entries = []
            current_row = 1
            for block in blocks:
                current_row = self._write_block_dispatcher(main_sheet, block, current_row, max_cols, toc_entries, AppConfig.EXCEL_MAIN_SHEET_NAME)
            
            self._apply_column_widths(main_sheet)
            self._write_toc(toc_sheet, toc_entries)
            workbook.active = workbook.index(toc_sheet)

# --- Helper Function for Easy Use ---
def convert_markdown_to_excel(md_file_path: str, output_excel_path: str, options: dict = None):
    """
    Main entry point to convert a markdown file to an Excel file.
    
    Args:
        md_file_path: Path to the input .md file
        output_excel_path: Path to save the output .xlsx file
        options: Optional dict, e.g. {'limit_max_width': True, 'max_width': 50}
    """
    input_path = Path(md_file_path)
    output_path = Path(output_excel_path)
    
    if not input_path.exists():
        raise FileNotFoundError(f"Input file not found: {input_path}")
        
    # Read Markdown
    with open(input_path, 'r', encoding='utf-8') as f:
        md_content = f.read()
        
    # Parse Markdown
    parser = MarkdownParser()
    blocks = parser.parse(md_content)
    
    # Write to Excel
    writer = MarkdownToExcelWriter(output_path, base_dir=input_path.parent, options=options)
    writer.write_blocks_to_excel(blocks)
    print(f"Successfully converted '{input_path.name}' to '{output_path.name}'")

